  if (days === 0) { var h = Math.round(m / 60); return h === 1 ? "un'ora fa" : h + ' ore fa'; }
  if (days === 1) return 'ieri alle ' + hm.format(new Date(t));
  if (days < 7) return days + ' giorni fa';
